export const GetDashboardSummaryResponse = zod.object({
  "totalChildren": zod.number(),
  "activeTherapyPlans": zod.number(),
  "upcomingAppointments": zod.number(),
  "pendingScreenings": zod.number(),
  "completedScreeningsThisMonth": zod.number(),
  "averageRiskScore": zod.number()
})


/**
 * @summary Get recent activity feed across all children
 */
export const GetDashboardActivityResponseItem = zod.object({
  "id": zod.number(),
  "activityType": zod.enum(['screening_completed', 'appointment_scheduled', 'therapy_updated', 'report_generated', 'child_added', 'milestone_reached']),
  "title": zod.string(),
  "description": zod.string(),
  "childName": zod.string().nullish(),
  "childId": zod.number().nullish(),
  "occurredAt": zod.string()
})
export const GetDashboardActivityResponse = zod.array(GetDashboardActivityResponseItem)


/**
 * @summary Get count of children by risk level
 */
export const GetRiskDistributionResponse = zod.object({
  "low": zod.number(),
  "moderate": zod.number(),
  "high": zod.number(),
  "critical": zod.number()
})


